      },
      {
        "reuse_pattern": "Stripe/Divination boundary separation",
        "description": "Enforce strict separation between payment rail (Stripe) and business logic/fulfillment (Divination) to prevent monolithic dependency."
      }
    ],
    "separate_contracts": [
      {
        "contract": "Stripe Payment Acceptance Enterprise",
        "reason": "Must remain a separately contracted sovereign rail to adhere to settlement law requiring imports under declared contracts."
      },
      {
        "contract": "Divination Settlement",
        "reason": "Maintains sovereign settlement status; root interacts via cross-settlement import rather than ownership."
      }
    ],
    "first_root_artifacts": [
      "Draft root offer schema",
      "Draft root service contract",
      "Conformance fixture package",
      "Internal unit/integration test suite"
    ],
    "reserved_leader_decisions": [
      "Live payment activation",
      "Definition of offering catalogs",
      "Pricing structures and tax configurations",
      "Refund policy terms and dispute resolution authority",
      "Selection of payout beneficiaries"
    ],
    "constraints": {
      "rejection_of_central_runtime": "Strictly prohibited; root must operate through sovereign, independently verified, and non-global patterns.",
      "operational_scope": "Focused on creating draft infrastructure and conformance testing only; no customer contact or live payment activation permitted."
    }
  }
}

